CREATE FUNCTION public.require_document_approval_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.document_status='approved' AND NOT EXISTS(SELECT 1 FROM public.clinical_drafts d WHERE d.consultation_id=NEW.id AND d.user_id=NEW.user_id AND d.status='approved' AND d.approved_at IS NOT NULL) THEN RAISE EXCEPTION 'Explicit clinician approval audit is required'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER approved_document_audit AFTER INSERT OR UPDATE ON public.consultations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.require_document_approval_audit();